/**
 * One out-of-office row per member per workspace.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, memberAbsences } from "@/server/db";
import type { MemberAbsenceRow } from "@/server/db";
import { brandId, brandStamp } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

export interface AbsenceWrite {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly delegateUserId: UserId | null;
  readonly startsAt: string;
  readonly endsAt: string;
  readonly note: string | null;
}

function toAbsence(row: MemberAbsenceRow): MemberAbsence {
  return {
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    delegateUserId:
      row.delegateUserId === null ? null : brandId<UserId>(row.delegateUserId),
    startsAt: brandStamp(row.startsAt),
    endsAt: brandStamp(row.endsAt),
    note: row.note,
  };
}

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, userId)),
    )
    .get();
  return row ? toAbsence(row) : null;
}

/** Insert or replace the member's single absence in this workspace. */
export async function upsertAbsence(input: AbsenceWrite): Promise<MemberAbsence> {
  const db = getDb();
  const existing = db
    .select({ id: memberAbsences.id })
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, input.orgId),
        eq(memberAbsences.userId, input.userId),
      ),
    )
    .get();

  const row = existing
    ? db
        .update(memberAbsences)
        .set({
          delegateUserId: input.delegateUserId,
          startsAt: input.startsAt,
          endsAt: input.endsAt,
          note: input.note,
        })
        .where(eq(memberAbsences.id, existing.id))
        .returning()
        .get()
    : db
        .insert(memberAbsences)
        .values({
          id: newId(),
          orgId: input.orgId,
          userId: input.userId,
          delegateUserId: input.delegateUserId,
          startsAt: input.startsAt,
          endsAt: input.endsAt,
          note: input.note,
        })
        .returning()
        .get();

  return toAbsence(row);
}

export async function deleteAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, userId)),
    )
    .run();
}

/** Drop every delegation that named `userId`, leaving the absence itself. */
export async function clearDelegate(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, userId),
      ),
    )
    .run();
}

