/**
 * True for the half-open window [startsAt, endsAt). A scheduled absence that
 * has not started is stored, but the member is not away yet.
 */
export function isAwayAt(
  absence: Pick<MemberAbsence, "startsAt" | "endsAt">,
  now: Date,
): boolean {
  const t = now.getTime();
  return t >= Date.parse(absence.startsAt) && t < Date.parse(absence.endsAt);
}

function hasEnded(
  absence: Pick<MemberAbsence, "endsAt">,
  now: Date,
): boolean {
  return now.getTime() >= Date.parse(absence.endsAt);
}

async function requireActiveMember(orgId: OrgId, userId: UserId): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

/**
 * Members who may change roles may set anyone's absence. Everyone else may
 * set only their own — that is not a role change, so it is not `can()`.
 */
function assertCanManageAbsence(actor: Actor, member: Member): void {
  if (actor.userId === member.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

/**
 * Replaces the member's absence. The end must be strictly after the start,
 * and a delegate must be a different active member of the same workspace.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  assertCanManageAbsence(actor, member);

  if (Date.parse(input.endsAt) <= Date.parse(input.startsAt)) {
    throw new Error("Absence end must be after the start");
  }

  const delegateUserId = input.delegateUserId ?? null;
  const note = input.note ?? null;

  if (note !== null && note.length > 200) {
    throw new Error("Absence note must be at most 200 characters");
  }

  if (delegateUserId !== null) {
    if (delegateUserId === input.userId) {
      throw new Error("A member cannot delegate their absence to themselves");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return absenceRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note,
  });
}

/** Clearing an absence that was never set is a no-op. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const member = await requireActiveMember(orgId, userId);
  assertCanManageAbsence(actor, member);
  await absenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The stored absence until it ends, including one that has not started.
 * Resolves to null once the window has ended or when none is set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  await requireActiveMember(orgId, userId);

  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (!absence || hasEnded(absence, new Date())) return null;
  return absence;
}

/**
 * The user who should be stored as assignee. Self-assignment is never
 * redirected, and a delegate who is themselves away is not chained further.
 */
export async function resolveAssignmentTarget(
  orgId: OrgId,
  actorUserId: UserId,
  assigneeId: UserId | null,
  now: Date,
): Promise<UserId | null> {
  if (assigneeId === null || assigneeId === actorUserId) return assigneeId;

  const absence = await absenceRepo.findAbsence(orgId, assigneeId);
  if (!absence || !isAwayAt(absence, now) || absence.delegateUserId === null) {
    return assigneeId;
  }
  return absence.delegateUserId;
}

/** Overdue alerts follow one delegate hop and otherwise stay with the assignee. */
export async function overdueAlertRecipient(
  orgId: OrgId,
  assigneeId: UserId,
  now: Date,
): Promise<UserId> {
  const absence = await absenceRepo.findAbsence(orgId, assigneeId);
  if (!absence || !isAwayAt(absence, now) || absence.delegateUserId === null) {
    return assigneeId;
  }
  return absence.delegateUserId;
}

/**
 * Mention alerts still go to each mentioned member. While one of them is away
 * with a delegate, that delegate is alerted too — once, even if also mentioned.
 */
export async function withAbsenceMentionDelegates(
  orgId: OrgId,
  mentionedUserIds: readonly UserId[],
  now: Date,
): Promise<UserId[]> {
  const recipients = [...mentionedUserIds];
  for (const userId of mentionedUserIds) {
    const absence = await absenceRepo.findAbsence(orgId, userId);
    if (
      absence &&
      isAwayAt(absence, now) &&
      absence.delegateUserId !== null &&
      !recipients.includes(absence.delegateUserId)
    ) {
      recipients.push(absence.delegateUserId);
    }
  }
  return recipients;
}

